import { readFileSync } from 'node:fs';
import { createRequire } from 'node:module';
import { createHash } from 'node:crypto';
import { join } from 'node:path';
const require = createRequire(join(process.cwd(), 'package.json'));
const ts = require('typescript');
const source = readFileSync(join(process.env.LOCALAPPDATA, 'Temp/emr-gw01-sql-split-2.121.0.ts'), 'utf8');
const sha = value => createHash('sha256').update(value, 'utf8').digest('hex');
if (sha(source) !== '005c59d49c164c72e60bbc9ab96b18bc7b811173b1702ded2e6bedabd2c688c0') throw Error('PUBLIC_SOURCE_SEAL');
const compiled = ts.transpileModule(source, { compilerOptions: { target: ts.ScriptTarget.ES2022, module: ts.ModuleKind.ES2022 }, reportDiagnostics: true });
if (compiled.diagnostics?.some(d => d.category === ts.DiagnosticCategory.Error)) throw Error('TRANSPILE');
const { splitAndTrim } = await import('data:text/javascript;base64,' + Buffer.from(compiled.outputText).toString('base64'));
const packet = JSON.parse(readFileSync('scripts/db/m03-dev-migration-packet.json', 'utf8'));
const known = [...packet.baseline, ...packet.pending];
if (known.length !== 9 || !known.every(m => sha(splitAndTrim(readFileSync(m.file, 'utf8')).join(String.fromCharCode(10))) === m.historySha256)) throw Error('HISTORICAL_PARITY');
const file = 'supabase/migrations/20261018070042_n8n_worker_gateway_admission.sql';
const content = readFileSync(file, 'utf8');
if (sha(content) !== '98ebdfad9fffa819773fdbee5e3b9b8374be8a6f58497593084aed4077e9b856') throw Error('FINAL_SOURCE_SEAL');
const statements = splitAndTrim(content);
console.log(JSON.stringify({ historicalMatches: known.length, statementCount: statements.length, historySha256: sha(statements.join(String.fromCharCode(10))) }));
